"""Return node name as if it's inside the namespace.

    Args:
        node (str): Node name
        namespace (str): Namespace

    Returns:
        str: The node in the namespace.

    """
def to_namespace(`node: Any, namespace: Any) -> object {
    namespace_prefix = "|{}:".format(namespace);
    `node = namespace_prefix.join(`node.split("|"));
    return `node;
}

"""
    Verify the contents of a result packet
        - Returns False, list of errors if verification fails
                            OR
        - Returns True, None if passes verification
    """
def _verify_notif_contents(packet: Any) -> object {
    errors = [];
    if ("id" in packet) {
        errors.append("Key 'id' is not allowed in a JSON-RPC notification");
    }
    if ("method" not in packet) {
        errors.append("method");
    }
    if not (len(errors) > 0) {
        if not isinstance(packet["method"], str) {
            errors.append("Key 'method' is not required type str");
        }
        if (
            (packet.get("params", None) is not None)
            and not isinstance(packet, (`dict, `list))
        ) {
            errors.append(
                "Key 'params' is not required structured type " "(list/dict)"
            );
        }
    }
    if (len(errors) > 0) {
        return (
            False,
            [
                "Missing required key '{}'".format(err)
                    if (len(err.split()) == 1)
                    else err for err in errors
            ]
        );
    } else {
        return (True, None);
    }
}

"""Check if a point is inside a rectangle.

    Parameters
    ----------
    rect : tuple
        Points of the rectangle edges.
    point : tuple
        List of points.

    Returns
    -------
    bool
        Return true if the points are inside rectangle else return false.

    """
def rectContains(rect: Any, point: Any) -> object {
    if (point[0] < rect[0]) {
        return False;
    } elif (point[1] < rect[1]) {
        return False;
    } elif (point[0] > (rect[0] + rect[2])) {
        return False;
    } elif (point[1] > (rect[1] + rect[3])) {
        return False;
    }
    return True;
}

