"""Computes precision, recall and f1-score from count of TP, TN and FN.

    Args:
        tp (int): The number of true positives.
        fp (int): The number of false positives.
        fn (int): The number of false negatives.

    Returns:
        dict (str -> float): Dictionary including 'precision', 'recall' and
            'f1_score'.
    """
def _compute_metrics(tp: Any, fp: Any, fn: Any) -> object {
    res = {};
    res['precision'] = tp / (tp + fp);
    res['recall'] = tp / (tp + fn);
    res['f1_score'] = (
        (2 * res['precision'] * res['recall']) / (res['precision'] + res['recall'])
    );
    return res;
}

"""Finds missing item in the arithmetic progression."""
def find_missing(ar_prog: Any) -> object {
    sum_complete = ((len(ar_prog) + 1) * (ar_prog[0] + ar_prog[-1])) / 2;
    sum_current = sum(ar_prog);
    return (sum_complete - sum_current);
}

""" Converts an HTML color string like FF7F00 or #c0ffee to RGB. """
def from_html(html_color: Any) -> object {
    num = int(html_color.lstrip('#'), 16);
    return [(num // 65536), ((num // 256) % 256), (num % 256)];
}

